import org.jsoup.Connection;
import org.jsoup.nodes.*;
import org.jsoup.select.Elements;
import org.jsoup.parser.Parser;
import org.junit.Test;
import static org.junit.Assert.*;

public class DocumentTest {

    @Test
    public void DocumentConstructorTest() {
        Document document = new Document("http://example.com");
        assertNotNull(document);
        assertEquals("http://example.com", document.baseUri());
    }

    @Test
    public void createShellTest() {
        Document document = Document.createShell("http://example.com");
        assertNotNull(document);
        assertEquals("<html>\n <head></head>\n <body></body>\n</html>", document.toString());
    }

    @Test
    public void locationTest() {
        Document document = new Document("http://example.com");
        assertEquals("http://example.com", document.location());
    }

    @Test
    public void connectionTest() {
        Document document = new Document("http://example.com");
        assertNotNull(document.connection());
    }

    @Test
    public void documentTypeTest() {
        Document document = new Document("Test");
        assertNull(document.documentType());
    }

    @Test
    public void headTest() {
        Document doc = Document.createShell("http://example.com");
        assertNotNull(doc.head());
    }

    @Test
    public void bodyTest() {
        Document doc = Document.createShell("http://example.com");
        assertNotNull(doc.body());
    }

    @Test
    public void formsTest() {
        Document document = new Document("Test");
        assertTrue(document.forms().isEmpty());
    }

    @Test(expected=IllegalArgumentException.class)
    public void expectFormTest() {
        Document document = new Document("Test");
        document.expectForm("#form");
    }

    @Test
    public void titleTest() {
        Document doc = Document.createShell("http://example.com");
        doc.title("Test title");
        assertEquals("Test title", doc.title());
    }

    @Test
    public void createElementTest() {
        Document doc = new Document("Test");
        assertNotNull(doc.createElement("div"));
    }

    @Test
    public void outerHtmlTest() {
        Document doc = Document.createShell("http://example.com");
        assertNotNull(doc.outerHtml());
    }

    @Test
    public void nodeNameTest() {
        Document doc = new Document("Test");
        assertEquals("#document", doc.nodeName());
    }

    @Test
    public void charsetTest() {
        Document doc = Document.createShell("http://example.com");
        assertEquals("UTF-8", doc.charset().displayName());
    }

    @Test
    public void updateMetaCharsetElementTest() {
        Document doc = Document.createShell("http://example.com");
        doc.updateMetaCharsetElement(false);
        assertFalse(doc.updateMetaCharsetElement());
    }

    @Test
    public void cloneTest() {
